 <header class="insight-article-header"><a href="/insights?category=${h(a.category)}" data-link="/insights?category=${h(a.category)}" class="insight-article-category">${h(cat?.name||a.category)}</a><h1>${h(a.title)}</h1><p>${h(a.subtitle)}</p><div class="insight-article-meta"><span class="insight-author-avatar">BA</span><span> B2B Atlas 编辑部</span><i></i><time datetime="${h(a.published_at)}">${h(articleDate(a))}</time><i></i><span>阅读约 ${a.reading_minutes} 分钟</span><button data-action="share-article" type="button"><span aria-hidden="true">↗</span> 复制文章链接</button></div></header>
